insert into equations(id,concept_id,title,latex,kind,assumptions,validity,meaning) values
  ('eq.vel','k.kecepatan','Kecepatan sesaat','v = \frac{dx}{dt}','definisi','["Posisi x(t) fungsi kontinu dan terdiferensialkan"]'::jsonb,'Gerak 1D; berlaku umum pada mekanika klasik.','Laju perubahan posisi terhadap waktu; tanda menunjukkan arah.'),
  ('eq.acc','k.percepatan','Percepatan sesaat','a = \frac{dv}{dt} = \frac{d^2x}{dt^2}','definisi','["v(t) terdiferensialkan"]'::jsonb,'Gerak 1D; versi vektor berlaku per komponen.','Seberapa cepat kecepatan berubah; nol bila kecepatan konstan.'),
  ('eq.vt','k.glbb','Kecepatan pada percepatan konstan','v = v_0 + at','turunan','["a konstan terhadap waktu"]'::jsonb,'Hanya untuk percepatan KONSTAN; kerangka inersial; mekanika Newton.','Kecepatan berubah linear terhadap waktu bila percepatan tetap.'),
  ('eq.xt','k.glbb','Posisi pada percepatan konstan','x = x_0 + v_0 t + \tfrac12 a t^2','turunan','["a konstan"]'::jsonb,'Hanya untuk percepatan konstan.','Luas di bawah grafik v-t adalah perpindahan.'),
  ('eq.v2','k.glbb','Hubungan kecepatan-posisi (tanpa waktu)','v^2 = v_0^2 + 2a(x-x_0)','turunan','["a konstan"]'::jsonb,'Hanya untuk percepatan konstan.','Berguna bila waktu tidak diketahui; juga bibit teorema usaha-energi.'),
  ('eq.acc_avg','k.percepatan','Percepatan rata-rata','\bar a = \frac{\Delta v}{\Delta t} = \frac{v_2 - v_1}{t_2 - t_1}','definisi','["Kecepatan v(t) diketahui pada dua saat t1 dan t2"]'::jsonb,'Selang waktu berhingga. Hasilnya hanya menggambarkan perubahan kecepatan rata-rata; percepatan sesungguhnya di setiap saat bisa berbeda-beda.','Sama seperti kemiringan garis yang menghubungkan dua titik pada grafik v-t.'),
  ('eq.acc_from_x','k.percepatan','Percepatan dari fungsi posisi kuadratik','x=x_0+v_0t+\tfrac12at^2\ \Rightarrow\ \frac{d^2x}{dt^2}=a','turunan','["Posisi berbentuk x(t) = x0 + v0 t + (1/2) a t^2 dengan x0, v0, a konstan"]'::jsonb,'Hanya memeriksa konsistensi untuk percepatan konstan; fungsi posisi lain memberi percepatan lain.','Menegaskan bahwa percepatan adalah turunan kedua posisi: kelengkungan grafik x-t.'),
  ('eq.range','k.proyektil','Jangkauan proyektil','R = \frac{v_0^2 \sin 2\theta}{g}','turunan','["Tanpa hambatan udara", "g konstan", "Permukaan datar, ketinggian awal = akhir", "Bumi diperlakukan datar"]'::jsonb,'Jangkauan kecil dibanding jari-jari Bumi; tanpa drag.','Jangkauan maksimum pada sudut 45 derajat (hanya dalam kondisi asumsi di atas).'),
  ('eq.ac','k.melingkar','Percepatan sentripetal','a_c = \frac{v^2}{r}','turunan','["Lintasan lingkaran jari-jari r", "Laju sudut omega konstan"]'::jsonb,'Derivasi ini untuk gerak melingkar beraturan. Untuk omega tidak konstan, komponen radial tetap -v^2/r tetapi ada tambahan percepatan tangensial.','Percepatan ada walaupun laju tetap, karena ARAH kecepatan berubah.'),
  ('eq.newton2','d.hukum2','Hukum II Newton','\sum \vec F = \frac{d\vec p}{dt} = m\vec a','hukum','["Kerangka inersial", "Massa konstan (untuk bentuk F = ma)"]'::jsonb,'Kerangka inersial; skala makroskopik (bukan kuantum). F = dp/dt tetap berlaku secara relativistik dengan p = gamma m v; bentuk F = ma hanya untuk m konstan dan v << c. Bukan hasil derivasi - ini hukum empiris.','Gaya total adalah penyebab perubahan gerak (percepatan).'),
  ('eq.work','e.kerja','Usaha oleh gaya','W = \int_{\vec r_1}^{\vec r_2} \vec F \cdot d\vec r','definisi','["Lintasan terdefinisi"]'::jsonb,'Berlaku umum dalam mekanika klasik.','Besaran skalar yang mengukur transfer energi lewat gaya.'),
  ('eq.wke','e.ek','Teorema usaha-energi kinetik','W_{net} = \Delta K, \quad K=\tfrac12 mv^2','turunan','["Massa konstan", "Kerangka inersial"]'::jsonb,'Mekanika Newton (v << c). Gambaran 1D; 3D identik dengan perkalian titik.','Usaha total menjadi perubahan energi kinetik.'),
  ('eq.pe','e.ep','Energi potensial dari gaya konservatif','\Delta U = -W_c, \quad F=-\frac{dU}{dx}','definisi','["Usaha tidak bergantung lintasan (gaya konservatif)", "F hanya fungsi posisi (tidak bergantung kecepatan atau waktu)", "U ditentukan sampai konstanta aditif; titik acuan bebas dipilih"]'::jsonb,'Hanya untuk gaya konservatif (gesekan tidak punya U).','U menyimpan kemampuan gaya konservatif untuk melakukan usaha.'),
  ('eq.mechE','e.kekekalan','Kekekalan energi mekanik','K + U = \text{konstan}','turunan','["Semua gaya yang melakukan usaha adalah konservatif (W_nc = 0)"]'::jsonb,'Berlaku bila usaha gaya nonkonservatif nol. Gaya yang tegak lurus gerak (normal, tegangan tali) boleh ada; gesekan kinetik mengubah energi mekanik menjadi kalor.','Energi berubah bentuk tetapi totalnya tetap, dalam batas asumsi.'),
  ('eq.impulse','p.momentum','Teorema impuls-momentum','\vec J = \int \vec F\,dt = \Delta\vec p','turunan','["Hukum II Newton dalam bentuk F = dp/dt"]'::jsonb,'Kerangka inersial; berlaku juga untuk gaya yang berubah terhadap waktu.','Gaya yang bekerja selama selang waktu mengubah momentum.'),
  ('eq.pcons','p.kekekalan','Kekekalan momentum linear','\sum\vec p = \text{konstan}\ (\vec F_{ext}=0)','turunan','["Gaya eksternal total nol", "Gaya internal mematuhi Hukum III Newton", "Derivasi untuk dua partikel; N partikel dengan menjumlahkan semua pasangan"]'::jsonb,'Kerangka inersial. Bila medan (mis. EM antar muatan bergerak) membawa momentum, yang kekal adalah momentum partikel + medan.','Gaya internal tidak mengubah momentum total.'),
  ('eq.shm','o.shm','Solusi osilasi harmonik sederhana','x(t)=A\cos(\omega t+\varphi),\ \omega=\sqrt{k/m}','turunan','["Gaya pemulih linear F = -kx", "Tanpa redaman"]'::jsonb,'Hanya untuk simpangan kecil di sekitar kesetimbangan (gaya linear).','Periode bergantung pada k dan m, bukan pada amplitudo.'),
  ('eq.pend','o.pendulum','Periode pendulum sederhana (sudut kecil)','T \approx 2\pi\sqrt{L/g}','aproksimasi','["Massa titik pada tali ringan tak mulur", "Tanpa gesekan di pivot dan tanpa hambatan udara", "g seragam, gerak planar", "Sudut kecil: sin(theta) ~ theta"]'::jsonb,'Hanya untuk simpangan kecil (< sekitar 10 derajat); untuk sudut besar periode bergantung amplitudo.','Periode tidak bergantung massa; hanya aproksimasi untuk sudut kecil.'),
  ('eq.torque_L','r.momsudut','Torsi dan laju perubahan momentum sudut','\vec\tau = \frac{d\vec L}{dt}','turunan','["Titik acuan tetap di kerangka inersial"]'::jsonb,'Kerangka inersial; titik acuan tetap.','Torsi adalah penyebab perubahan momentum sudut.'),
  ('eq.kepler2','g.kepler','Hukum Kepler II (luas sapuan)','\frac{dA}{dt}=\frac{L}{2m}=\text{konstan}','turunan','["Gaya sentral (torsi terhadap pusat nol)"]'::jsonb,'Setiap gaya sentral, bukan hanya gravitasi. Secara historis Kepler II adalah temuan empiris; di sini ditunjukkan sebagai konsekuensi kekekalan momentum sudut.','Hukum Kepler II adalah kekekalan momentum sudut.'),
  ('eq.bernoulli','f.bernoulli','Persamaan Bernoulli','p + \tfrac12\rho v^2 + \rho g y = \text{konstan}','turunan','["Fluida tak termampatkan", "Tak kental (nonviscous)", "Aliran tunak (steady)", "Sepanjang satu garis arus", "Tanpa pompa/turbin; g seragam"]'::jsonb,'Gagal untuk fluida kental, aliran turbulen, atau termampatkan (kompresibilitas mulai penting pada Mach sekitar 0,3 ke atas).','Bernoulli adalah kekekalan energi untuk fluida ideal.'),
  ('eq.el','l.eulerlagrange','Persamaan Euler-Lagrange','\frac{d}{dt}\frac{\partial L}{\partial\dot q}-\frac{\partial L}{\partial q}=0','turunan','["Prinsip aksi stasioner dipostulatkan (bukan diturunkan di sini)", "Koordinat umum bebas (kendala holonomik)", "Lagrangian mulus (integran kontinu)"]'::jsonb,'Berlaku untuk sistem yang memiliki Lagrangian (termasuk potensial bergantung kecepatan/waktu, mis. elektromagnetik); gaya disipatif murni (gesekan kinetik) tidak punya Lagrangian sederhana.','Persamaan gerak dari satu fungsi skalar (L), bebas pilihan koordinat.'),
  ('eq.el_newton','l.eulerlagrange','Euler-Lagrange menghasilkan Hukum II Newton','m\ddot x=-\frac{dU}{dx}','turunan','["L = K - U", "Satu dimensi, koordinat kartesius"]'::jsonb,'Menunjukkan konsistensi dengan mekanika Newton.','Mekanika Lagrangian mencakup Newton sebagai kasus khusus.'),
  ('eq.maxwell_wave','x.gelombang_em','Persamaan gelombang EM di ruang hampa','\nabla^2\vec E=\mu_0\varepsilon_0\frac{\partial^2\vec E}{\partial t^2},\quad c=\frac{1}{\sqrt{\mu_0\varepsilon_0}}','turunan','["Persamaan Maxwell (Gauss, Faraday, Ampere-Maxwell) diterima sebagai hukum dasar", "Ruang hampa: tanpa muatan dan arus (rho = 0, J = 0)", "Medan cukup mulus (turunan ruang dan waktu dapat dipertukarkan)"]'::jsonb,'Ruang hampa. Di dalam materi, mu0 dan epsilon0 diganti mu dan epsilon hanya untuk dielektrik linear, homogen, isotropik, tak berdispersi, tanpa muatan/arus bebas.','Cahaya adalah gelombang elektromagnetik; c ditentukan oleh konstanta listrik dan magnet.'),
  ('eq.timedil','sr.dilatasi','Dilatasi waktu','\Delta t=\gamma\,\Delta\tau,\quad \gamma=\frac{1}{\sqrt{1-v^2/c^2}}','turunan','["Kecepatan cahaya sama di semua kerangka inersial (postulat 2)", "Prinsip relativitas (postulat 1)", "Jam cahaya tegak lurus terhadap v; panjang transversal d sama di kedua kerangka (konsekuensi prinsip relativitas)", "Delta tau = waktu proper: selang antara dua kejadian di tempat yang sama dalam kerangka diam jam"]'::jsonb,'Kerangka inersial; berlaku untuk semua v < c.','Jam yang bergerak terukur lebih lambat oleh pengamat yang relatif bergerak.'),
  ('eq.E2','sr.momenergi','Hubungan energi-momentum relativistik','E^2=(pc)^2+(mc^2)^2','turunan','["Definisi relativistik: p = gamma m v dan E = gamma m c^2 (m = massa diam)", "Faktor gamma dari kedua postulat relativitas khusus"]'::jsonb,'Relativitas khusus; berlaku untuk benda bermassa dengan semua v < c. Untuk foton (m = 0), E = pc diterima sebagai limit/perluasan (norma empat-momentum nol), bukan hasil derivasi ini.','Benda diam (p = 0): E = mc^2. Foton: E = pc diterima sebagai limit m -> 0.'),
  ('eq.bohr','a.bohr','Tingkat energi atom Bohr (hidrogen, Z = 1)','E_n=-\frac{13{,}6\ \text{eV}}{n^2}','model','["Orbit lingkaran klasik", "Postulat Bohr 1: orbit stasioner tidak memancar (bertentangan dengan elektrodinamika klasik)", "Postulat Bohr 2: L = n hbar; transisi memancarkan foton dengan h nu = E_i - E_f", "Inti diam (massa tereduksi diabaikan), satu elektron"]'::jsonb,'Hidrogen (Z = 1) dalam aproksimasi inti diam; untuk ion mirip-hidrogen E_n memuat faktor Z^2. Gagal secara kualitatif: keadaan dasar Bohr punya L = hbar, padahal yang benar L = 0; tidak menjelaskan spin, struktur halus, intensitas garis, atau atom multielektron.','Menjelaskan spektrum hidrogen dengan baik, tetapi kuantisasinya dipostulatkan; dijelaskan lebih mendalam oleh persamaan Schrodinger.'),
  ('eq.tdse','q.tdse','Persamaan Schrodinger bergantung waktu','i\hbar\frac{\partial\psi}{\partial t}=-\frac{\hbar^2}{2m}\frac{\partial^2\psi}{\partial x^2}+V\psi','postulat','["Postulat mekanika kuantum", "Partikel non-relativistik", "V riil (agar peluang kekal)", "Persamaan linear dalam psi"]'::jsonb,'v << c; tidak menjelaskan spin atau pasangan partikel-antipartikel tanpa perluasan.','Tidak diturunkan dari fisika klasik: ia adalah postulat yang dimotivasi oleh gelombang materi dan diuji eksperimen.'),
  ('eq.tise','q.tise','Persamaan Schrodinger tak bergantung waktu','-\frac{\hbar^2}{2m}\frac{d^2\varphi}{dx^2}+V\varphi=E\varphi','turunan','["V tidak bergantung waktu", "Solusi dapat dipisah: psi = phi(x) T(t)"]'::jsonb,'Hanya untuk potensial yang tidak bergantung waktu.','Keadaan stasioner: rapat peluang tidak berubah terhadap waktu.'),
  ('eq.uncertainty','q.komutator','Prinsip ketidakpastian umum','\sigma_A\sigma_B\ge\tfrac12\left|\langle[\hat A,\hat B]\rangle\right|','turunan','["Operator hermitian A dan B", "Keadaan ternormalisasi dan berada di domain operator; variansi berhingga"]'::jsonb,'Mekanika kuantum; bentuk x-p: sigma_x sigma_p >= hbar/2 dari [x,p] = i hbar.','Ketidakpastian bukan cacat alat ukur: ia lahir dari non-komutatifnya observabel.'),
  ('eq.kinetic_p','t.kinetik','Tekanan dari teori kinetik','pV=\tfrac13Nm\langle v^2\rangle\ \Rightarrow\ \langle K\rangle=\tfrac32kT','turunan','["Gas ideal: tumbukan elastis dengan dinding", "Tanpa interaksi antarmolekul", "Distribusi kecepatan isotropik", "pV = NkT diterima sebagai hukum gas empiris, dipakai untuk MENGIDENTIFIKASI suhu T", "Gaya pada dinding dari Hukum III Newton (dinding mendorong balik dengan impuls yang sama)"]'::jsonb,'Gas encer; non-relativistik (v << c); suhu tidak terlalu rendah (efek kuantum diabaikan). Hasil 3/2 kT adalah energi kinetik TRANSLASI rata-rata per molekul.','Suhu adalah ukuran energi kinetik acak rata-rata molekul.'),
  ('eq.carnot','t.carnot','Efisiensi Carnot','\eta=1-\frac{T_c}{T_h}','turunan','["Gas ideal dengan gamma konstan", "Siklus reversibel (proses kuasi-statik)", "Dua isoterm dan dua adiabat; T adalah suhu gas ideal (setara suhu termodinamika)"]'::jsonb,'Efisiensi siklus Carnot gas ideal. Bahwa ini batas atas untuk SEMUA mesin kalor antara T_h dan T_c dibuktikan terpisah dengan hukum II termodinamika (t.hukum2), bukan oleh derivasi ini.','Efisiensi hanya bergantung pada dua suhu reservoir. (Teorema Carnot: tidak ada mesin yang lebih efisien - dibuktikan dengan hukum II.)')
insert into equation_steps(equation_id,step_no,latex,reason) values
  ('eq.vel',1,'\bar v = \frac{\Delta x}{\Delta t}','Kecepatan rata-rata didefinisikan sebagai perpindahan per selang waktu.'),
  ('eq.vel',2,'v = \lim_{\Delta t \to 0} \frac{x(t+\Delta t)-x(t)}{\Delta t}','Kecepatan sesaat adalah limit kecepatan rata-rata saat selang waktu menuju nol (konsep limit).'),
  ('eq.vel',3,'v = \frac{dx}{dt}','Limit tersebut adalah definisi turunan x terhadap t.'),
  ('eq.acc',1,'\bar a = \frac{\Delta v}{\Delta t}','Analog dengan kecepatan rata-rata, tetapi untuk perubahan kecepatan.'),
  ('eq.acc',2,'a = \lim_{\Delta t \to 0}\frac{\Delta v}{\Delta t} = \frac{dv}{dt}','Limit, sama seperti definisi kecepatan sesaat.'),
  ('eq.acc',3,'a = \frac{d}{dt}\left(\frac{dx}{dt}\right) = \frac{d^2x}{dt^2}','Substitusi v = dx/dt dari eq.vel.'),
  ('eq.vt',1,'\frac{dv}{dt} = a','Mulai dari definisi percepatan (eq.acc).'),
  ('eq.vt',2,'dv = a\,dt','Pisahkan variabel.'),
  ('eq.vt',3,'\int_{v_0}^{v} dv'' = a\int_0^t dt''','Integrasikan kedua sisi; a konstan sehingga keluar dari integral.'),
  ('eq.vt',4,'v - v_0 = at \;\Rightarrow\; v = v_0 + at','Hitung integral tentu.'),
  ('eq.xt',1,'\frac{dx}{dt} = v_0 + at','Gunakan v(t) dari eq.vt pada definisi kecepatan (eq.vel).'),
  ('eq.xt',2,'\int_{x_0}^{x} dx'' = \int_0^t (v_0 + at'')\,dt''','Pisahkan variabel dan integrasikan.'),
  ('eq.xt',3,'x - x_0 = v_0 t + \tfrac12 a t^2','Hitung integral tentu.'),
  ('eq.v2',1,'a = \frac{dv}{dt} = \frac{dv}{dx}\frac{dx}{dt} = v\frac{dv}{dx}','Aturan rantai: ganti variabel bebas dari t ke x.'),
  ('eq.v2',2,'a\,dx = v\,dv','Pisahkan variabel.'),
  ('eq.v2',3,'a(x-x_0) = \tfrac12 (v^2 - v_0^2)','Integrasikan; a konstan.'),
  ('eq.v2',4,'v^2 = v_0^2 + 2a(x-x_0)','Susun ulang.'),
  ('eq.acc_avg',1,'v_1 = v(t_1),\quad v_2 = v(t_2)','Ambil kecepatan pada dua saat yang berbeda.'),
  ('eq.acc_avg',2,'\Delta v = v_2 - v_1,\quad \Delta t = t_2 - t_1','Hitung perubahan kecepatan dan selang waktunya; tanda Delta v membawa informasi arah.'),
  ('eq.acc_avg',3,'\bar a = \frac{\Delta v}{\Delta t}','Definisi: perubahan kecepatan per satuan waktu. Satuannya (m/s)/s = m/s^2.'),
  ('eq.acc_from_x',1,'x(t)=x_0+v_0t+\tfrac12at^2','Fungsi posisi gerak dengan percepatan konstan (eq.xt).'),
  ('eq.acc_from_x',2,'v=\frac{dx}{dt}=0+v_0\cdot1+\tfrac12a\cdot2t=v_0+at','Turunkan suku demi suku (eq.vel): turunan konstanta = 0, turunan t = 1, turunan t^2 = 2t.'),
  ('eq.acc_from_x',3,'a=\frac{dv}{dt}=0+a=a','Turunkan sekali lagi (eq.acc): v0 konstan sehingga turunannya 0, turunan a t terhadap t adalah a.'),
  ('eq.acc_from_x',4,'\frac{d^2x}{dt^2}=a','Hasilnya a, sama dengan percepatan yang dipakai membangun x(t): konsisten.'),
  ('eq.range',1,'x = v_0\cos\theta\, t','Komponen horizontal: a_x = 0, gunakan eq.xt.'),
  ('eq.range',2,'y = v_0\sin\theta\, t - \tfrac12 g t^2','Komponen vertikal: a_y = -g, gunakan eq.xt.'),
  ('eq.range',3,'y=0 \Rightarrow t = \frac{2 v_0 \sin\theta}{g}','Waktu terbang: y = 0 punya dua akar (t = 0 adalah titik awal); ambil akar nontrivial.'),
  ('eq.range',4,'R = v_0\cos\theta \cdot \frac{2v_0\sin\theta}{g} = \frac{v_0^2 \sin 2\theta}{g}','Substitusi t ke x dan gunakan 2 sin cos = sin 2theta.'),
  ('eq.ac',1,'\vec r(t) = r(\cos\omega t,\ \sin\omega t)','Parametrisasi lingkaran dengan laju sudut konstan.'),
  ('eq.ac',2,'\vec v = \frac{d\vec r}{dt} = r\omega(-\sin\omega t,\ \cos\omega t)','Turunan pertama (kecepatan); besarnya v = r omega.'),
  ('eq.ac',3,'\vec a = \frac{d\vec v}{dt} = -\omega^2 \vec r','Turunan kedua: percepatan berlawanan arah vektor posisi, yaitu menuju pusat.'),
  ('eq.ac',4,'a = \omega^2 r = \frac{v^2}{r}','Besar a, dengan v = omega r.'),
  ('eq.newton2',1,'\vec p = m\vec v','Definisi momentum linear.'),
  ('eq.newton2',2,'\sum\vec F = \frac{d\vec p}{dt}','Pernyataan hukum: gaya total menentukan laju perubahan momentum (didukung eksperimen).'),
  ('eq.newton2',3,'\sum\vec F = m\frac{d\vec v}{dt} = m\vec a','Bila m konstan, m keluar dari turunan.'),
  ('eq.work',1,'W = F\,\Delta x \quad (F\ \text{konstan, searah gerak})','Kasus paling sederhana sebagai intuisi.'),
  ('eq.work',2,'dW = \vec F\cdot d\vec r','Untuk perpindahan sangat kecil, gaya dianggap konstan (perkalian titik menangkap komponen searah gerak).'),
  ('eq.work',3,'W = \int \vec F\cdot d\vec r','Jumlahkan seluruh kontribusi sepanjang lintasan (integral garis).'),
  ('eq.wke',1,'W_{net} = \int F\,dx = \int m\frac{dv}{dt}\,dx','Substitusi F = ma = m dv/dt (eq.newton2).'),
  ('eq.wke',2,'dx = v\,dt \Rightarrow W_{net} = \int m v\,dv','Ganti dx dengan v dt sehingga variabel integrasi menjadi v.'),
  ('eq.wke',3,'W_{net} = \tfrac12 m v_f^2 - \tfrac12 m v_i^2','Hitung integral; m konstan.'),
  ('eq.wke',4,'K \equiv \tfrac12 mv^2 \Rightarrow W_{net}=\Delta K','Definisikan energi kinetik.'),
  ('eq.pe',1,'W_c \text{ tidak bergantung lintasan}','Ini definisi gaya konservatif; membuat U fungsi posisi saja.'),
  ('eq.pe',2,'\Delta U \equiv -W_c = -\int F\,dx','Definisi perubahan energi potensial.'),
  ('eq.pe',3,'F = -\frac{dU}{dx}','Turunkan kedua sisi terhadap x (teorema fundamental kalkulus).'),
  ('eq.mechE',1,'W_{net} = W_c = \Delta K','Teorema usaha-energi (eq.wke) dengan hanya gaya konservatif.'),
  ('eq.mechE',2,'W_c = -\Delta U','Definisi energi potensial (eq.pe).'),
  ('eq.mechE',3,'\Delta K = -\Delta U \Rightarrow \Delta(K+U)=0','Gabungkan kedua persamaan.'),
  ('eq.impulse',1,'\vec F = \frac{d\vec p}{dt}','Hukum II Newton (eq.newton2).'),
  ('eq.impulse',2,'\int_{t_1}^{t_2} \vec F\,dt = \int_{\vec p_1}^{\vec p_2} d\vec p','Integrasikan terhadap waktu.'),
  ('eq.impulse',3,'\vec J = \Delta\vec p','Hitung; ruas kiri didefinisikan sebagai impuls.'),
  ('eq.pcons',1,'\frac{d\vec p_1}{dt}=\vec F_{12},\quad \frac{d\vec p_2}{dt}=\vec F_{21}','Hukum II Newton untuk tiap partikel; hanya gaya internal.'),
  ('eq.pcons',2,'\vec F_{12} = -\vec F_{21}','Hukum III Newton.'),
  ('eq.pcons',3,'\frac{d}{dt}(\vec p_1+\vec p_2)=0','Jumlahkan; gaya internal saling meniadakan.'),
  ('eq.shm',1,'m\ddot x = -kx','Hukum II Newton dengan gaya pegas (Hooke).'),
  ('eq.shm',2,'\ddot x + \omega^2 x = 0,\quad \omega^2 = k/m','Susun ulang dan beri nama omega^2.'),
  ('eq.shm',3,'x = e^{\lambda t} \Rightarrow \lambda^2 + \omega^2 = 0 \Rightarrow \lambda=\pm i\omega','Coba solusi eksponensial (persamaan diferensial orde-2 linear), dapatkan persamaan karakteristik.'),
  ('eq.shm',4,'x = C_1 e^{i\omega t}+C_2 e^{-i\omega t}','Solusi umum dari dua akar.'),
  ('eq.shm',5,'x(t)=A\cos(\omega t+\varphi)','Syarat x real dan rumus Euler memberi bentuk kosinus; A dan phi ditentukan oleh syarat awal.'),
  ('eq.pend',1,'I\ddot\theta = -mgL\sin\theta,\quad I = mL^2','Dinamika rotasi (tau = I theta-dot-dot, eq.torque_L): torsi pemulih dari gravitasi.'),
  ('eq.pend',2,'\ddot\theta = -\frac{g}{L}\sin\theta','Sederhanakan; massa saling meniadakan.'),
  ('eq.pend',3,'\sin\theta \approx \theta','Ekspansi Taylor orde pertama (aproksimasi sudut kecil).'),
  ('eq.pend',4,'\ddot\theta + \frac{g}{L}\theta = 0 \Rightarrow \omega=\sqrt{g/L}','Bentuknya sama dengan eq.shm.'),
  ('eq.pend',5,'T = \frac{2\pi}{\omega}=2\pi\sqrt{L/g}','Periode dari frekuensi sudut.'),
  ('eq.torque_L',1,'\vec L = \vec r\times\vec p','Definisi momentum sudut partikel.'),
  ('eq.torque_L',2,'\frac{d\vec L}{dt} = \frac{d\vec r}{dt}\times\vec p + \vec r\times\frac{d\vec p}{dt}','Aturan turunan hasil kali untuk perkalian silang.'),
  ('eq.torque_L',3,'\frac{d\vec r}{dt}\times\vec p = \vec v\times m\vec v = 0','Vektor sejajar: perkalian silang nol.'),
  ('eq.torque_L',4,'\frac{d\vec L}{dt}=\vec r\times\vec F=\vec\tau','Gunakan eq.newton2 dan definisi torsi.'),
  ('eq.kepler2',1,'\vec\tau=\vec r\times\vec F_{sentral}=0 \Rightarrow \vec L=\text{konstan}','Gaya sentral sejajar r sehingga torsi nol (eq.torque_L); L konstan berarti gerak terkurung pada satu bidang tegak lurus L, sehingga koordinat polar di bidang itu sah.'),
  ('eq.kepler2',2,'dA = \tfrac12 r^2 d\theta','Luas sektor sempit yang disapu vektor posisi.'),
  ('eq.kepler2',3,'L = mr^2\dot\theta \Rightarrow \frac{dA}{dt}=\tfrac12 r^2\dot\theta=\frac{L}{2m}','Ganti theta-dot dengan L; L konstan sehingga dA/dt konstan.'),
  ('eq.bernoulli',1,'\Delta V_1=\Delta V_2=\Delta V','Persamaan kontinuitas: volume yang masuk sama dengan volume yang keluar (tak termampatkan).'),
  ('eq.bernoulli',2,'W_{tek}=(p_1-p_2)\Delta V','Usaha oleh tekanan pada elemen fluida; tekanan pada dinding samping tabung arus tegak lurus gerak sehingga tidak melakukan usaha.'),
  ('eq.bernoulli',3,'\Delta K=\tfrac12\rho\Delta V(v_2^2-v_1^2),\quad \Delta U=\rho\Delta V g(y_2-y_1)','Perubahan energi kinetik dan potensial elemen.'),
  ('eq.bernoulli',4,'W_{tek}+W_{grav}=\Delta K,\ W_{grav}=-\Delta U\ \Rightarrow\ W_{tek}=\Delta K+\Delta U','Teorema usaha-energi (eq.wke) dengan usaha gravitasi = -Delta U (eq.pe).'),
  ('eq.bernoulli',5,'p_1+\tfrac12\rho v_1^2+\rho g y_1 = p_2+\tfrac12\rho v_2^2+\rho g y_2','Bagi dengan Delta V dan kelompokkan indeks 1 dan 2.'),
  ('eq.el',1,'S[q]=\int_{t_1}^{t_2}L(q,\dot q,t)\,dt','Aksi didefinisikan sebagai integral Lagrangian.'),
  ('eq.el',2,'q\to q+\epsilon\eta,\ \eta(t_1)=\eta(t_2)=0','Variasi lintasan dengan ujung tetap.'),
  ('eq.el',3,'\frac{dS}{d\epsilon}\Big|_0=\int\left(\frac{\partial L}{\partial q}\eta+\frac{\partial L}{\partial\dot q}\dot\eta\right)dt=0','Syarat stasioner: aksi tidak berubah di orde pertama.'),
  ('eq.el',4,'\int\frac{\partial L}{\partial\dot q}\dot\eta\,dt = -\int \frac{d}{dt}\!\left(\frac{\partial L}{\partial\dot q}\right)\eta\,dt','Integrasi parsial; suku batas hilang karena eta = 0 di ujung.'),
  ('eq.el',5,'\int\left[\frac{\partial L}{\partial q}-\frac{d}{dt}\frac{\partial L}{\partial\dot q}\right]\eta\,dt=0\ \forall\eta','Gabungkan suku-suku.'),
  ('eq.el',6,'\Rightarrow \frac{d}{dt}\frac{\partial L}{\partial\dot q}-\frac{\partial L}{\partial q}=0','Lema dasar kalkulus variasi: integran harus nol.'),
  ('eq.el_newton',1,'L=\tfrac12 m\dot x^2-U(x)','Pilih Lagrangian L = K - U.'),
  ('eq.el_newton',2,'\frac{\partial L}{\partial\dot x}=m\dot x\ \Rightarrow\ \frac{d}{dt}\frac{\partial L}{\partial\dot x}=m\ddot x','Hitung suku pertama eq.el.'),
  ('eq.el_newton',3,'\frac{\partial L}{\partial x}=-\frac{dU}{dx}','Hitung suku kedua.'),
  ('eq.el_newton',4,'m\ddot x+\frac{dU}{dx}=0\ \Rightarrow\ m\ddot x=F','Masukkan ke eq.el dan gunakan F = -dU/dx (eq.pe).'),
  ('eq.maxwell_wave',1,'\nabla\times\vec E=-\frac{\partial\vec B}{\partial t},\quad \nabla\times\vec B=\mu_0\varepsilon_0\frac{\partial\vec E}{\partial t}','Hukum Faraday dan Ampere-Maxwell di ruang hampa.'),
  ('eq.maxwell_wave',2,'\nabla\times(\nabla\times\vec E)=-\frac{\partial}{\partial t}(\nabla\times\vec B)=-\mu_0\varepsilon_0\frac{\partial^2\vec E}{\partial t^2}','Ambil curl hukum Faraday, lalu masukkan hukum Ampere-Maxwell.'),
  ('eq.maxwell_wave',3,'\nabla\times(\nabla\times\vec E)=\nabla(\nabla\cdot\vec E)-\nabla^2\vec E=-\nabla^2\vec E','Identitas vektor, dan Gauss ruang hampa: divergensi E = 0.'),
  ('eq.maxwell_wave',4,'\nabla^2\vec E=\mu_0\varepsilon_0\frac{\partial^2\vec E}{\partial t^2}','Samakan kedua hasil.'),
  ('eq.maxwell_wave',5,'v=\frac{1}{\sqrt{\mu_0\varepsilon_0}}=c','Bandingkan dengan persamaan gelombang bentuk standar; kecepatan rambat adalah c.'),
  ('eq.timedil',1,'\Delta\tau=\frac{2d}{c}','Jam cahaya: dalam kerangka diam jam, cahaya menempuh jarak 2d.'),
  ('eq.timedil',2,'\left(\frac{c\Delta t}{2}\right)^2=d^2+\left(\frac{v\Delta t}{2}\right)^2','Dalam kerangka pengamat, jam bergerak sehingga lintasan cahaya miring; c tetap (postulat 2). Gunakan Pythagoras.'),
  ('eq.timedil',3,'\Delta t^2\left(c^2-v^2\right)=4d^2','Susun ulang.'),
  ('eq.timedil',4,'\Delta t=\frac{2d/c}{\sqrt{1-v^2/c^2}}=\gamma\Delta\tau','Substitusi 2d/c = Delta tau.'),
  ('eq.E2',1,'E=\gamma mc^2,\quad p=\gamma mv,\quad \gamma=\frac{1}{\sqrt{1-v^2/c^2}}','Definisi energi dan momentum relativistik; gamma berasal dari transformasi Lorentz/dilatasi waktu (eq.timedil).'),
  ('eq.E2',2,'E^2-(pc)^2=\gamma^2m^2c^4\left(1-\frac{v^2}{c^2}\right)','Kuadratkan keduanya dan kurangkan.'),
  ('eq.E2',3,'\gamma^2\left(1-\frac{v^2}{c^2}\right)=1\ \Rightarrow\ E^2-(pc)^2=(mc^2)^2','Gunakan definisi gamma.'),
  ('eq.E2',4,'P^\mu=(E/c,\vec p),\ P^\mu P_\mu=(mc)^2','Tafsir geometris: kombinasi ini adalah norma empat-momentum, invarian di semua kerangka inersial.'),
  ('eq.bohr',1,'\frac{mv^2}{r}=\frac{ke^2}{r^2}','Hukum II Newton untuk orbit lingkaran dengan gaya Coulomb (eq.ac).'),
  ('eq.bohr',2,'mvr=n\hbar\quad (\text{postulat})','Kuantisasi momentum sudut - ini asumsi baru Bohr, bukan hasil derivasi.'),
  ('eq.bohr',3,'r_n=\frac{n^2\hbar^2}{mke^2}=n^2a_0','Eliminasi v dari dua persamaan.'),
  ('eq.bohr',4,'E=\tfrac12mv^2-\frac{ke^2}{r}=-\frac{ke^2}{2r}','Energi total dengan v dari langkah pertama.'),
  ('eq.bohr',5,'E_n=-\frac{mk^2e^4}{2\hbar^2}\frac{1}{n^2}=-\frac{13{,}6\ \text{eV}}{n^2}','Substitusi r_n.'),
  ('eq.tdse',1,'\psi=e^{i(kx-\omega t)},\ p=\hbar k,\ E=\hbar\omega','Heuristik (bukan derivasi): gelombang bidang untuk partikel bebas, hubungan de Broglie dan Planck.'),
  ('eq.tdse',2,'E=\frac{p^2}{2m}+V','Energi klasik partikel non-relativistik.'),
  ('eq.tdse',3,'i\hbar\frac{\partial}{\partial t}\to E,\quad -i\hbar\frac{\partial}{\partial x}\to p','Aturan korespondensi dari bentuk gelombang bidang.'),
  ('eq.tdse',4,'i\hbar\partial_t\psi=-\frac{\hbar^2}{2m}\partial_x^2\psi+V\psi','Terapkan operator ke psi. Kecocokan dengan eksperimen adalah pembenarannya.'),
  ('eq.tise',1,'\psi(x,t)=\varphi(x)T(t)','Separasi variabel.'),
  ('eq.tise',2,'i\hbar\frac{T''}{T}=\frac{1}{\varphi}\left[-\frac{\hbar^2}{2m}\varphi''''+V\varphi\right]','Substitusi ke eq.tdse dan bagi dengan phi T.'),
  ('eq.tise',3,'\text{kedua sisi} = E\ (\text{konstanta})','Ruas kiri hanya bergantung t, ruas kanan hanya x, jadi keduanya konstanta.'),
  ('eq.tise',4,'T(t)=e^{-iEt/\hbar}','Selesaikan persamaan waktu.'),
  ('eq.tise',5,'-\frac{\hbar^2}{2m}\varphi''''+V\varphi=E\varphi','Persamaan ruang; E menjadi nilai eigen energi.'),
  ('eq.uncertainty',1,'\sigma_A^2\sigma_B^2\ge|\langle f|g\rangle|^2','Definisikan f = (A - <A>)psi dan g = (B - <B>)psi. Karena A, B hermitian: sigma_A^2 = <f|f> dan sigma_B^2 = <g|g>; lalu gunakan ketaksamaan Cauchy-Schwarz <f|f><g|g> >= |<f|g>|^2.'),
  ('eq.uncertainty',2,'\langle f|g\rangle=\tfrac12\langle\{\Delta A,\Delta B\}\rangle+\tfrac12\langle[\hat A,\hat B]\rangle','Pisahkan ke bagian simetris (riil) dan antisimetris (imajiner murni).'),
  ('eq.uncertainty',3,'|\langle f|g\rangle|^2\ge\left|\tfrac12\langle[\hat A,\hat B]\rangle\right|^2','Buang bagian riil yang tidak negatif.'),
  ('eq.uncertainty',4,'[\hat x,\hat p]=i\hbar\ \Rightarrow\ \sigma_x\sigma_p\ge\hbar/2','Kasus posisi-momentum.'),
  ('eq.kinetic_p',1,'\Delta p=2mv_x\ \text{per tumbukan}','Tumbukan elastis dengan dinding membalik v_x.'),
  ('eq.kinetic_p',2,'F=\frac{N}{V}\cdot\tfrac12 A v_x\Delta t\cdot\frac{2mv_x}{\Delta t}','Jumlah tumbukan per selang waktu (setengah molekul bergerak ke dinding), kali impuls per tumbukan (eq.impulse).'),
  ('eq.kinetic_p',3,'p=\frac{F}{A}=\frac{N}{V}m\langle v_x^2\rangle=\tfrac13\frac{N}{V}m\langle v^2\rangle','Isotropi: <v_x^2> = <v^2>/3.'),
  ('eq.kinetic_p',4,'pV=NkT\ \Rightarrow\ \tfrac13 m\langle v^2\rangle=kT','Identifikasi suhu: samakan dengan hukum gas empiris pV = NkT.'),
  ('eq.kinetic_p',5,'\langle K\rangle=\tfrac12m\langle v^2\rangle=\tfrac32kT','Energi kinetik translasi rata-rata per molekul.'),
  ('eq.carnot',1,'Q_h=nRT_h\ln\frac{V_2}{V_1},\quad Q_c=nRT_c\ln\frac{V_3}{V_4}','Kalor pada dua isoterm (energi dalam gas ideal tidak berubah pada isoterm).'),
  ('eq.carnot',2,'T_hV_2^{\gamma-1}=T_cV_3^{\gamma-1},\quad T_hV_1^{\gamma-1}=T_cV_4^{\gamma-1}\ \Rightarrow\ \frac{V_2}{V_1}=\frac{V_3}{V_4}','Tulis TV^(gamma-1) = konstan untuk kedua adiabat (2->3 dan 4->1), lalu bagi persamaannya.'),
  ('eq.carnot',3,'\frac{Q_c}{Q_h}=\frac{T_c}{T_h}','Bagi kedua kalor; logaritma sama.'),
  ('eq.carnot',4,'\eta=\frac{W}{Q_h}=1-\frac{Q_c}{Q_h}=1-\frac{T_c}{T_h}','Definisi efisiensi dan hukum I (W = Q_h - Q_c).')
